func portalIssuesURL(data PortalPageData) string {
	if data.CanManageIssues {
		return "/app/anliegen/board"
	}
	return "/app/anliegen"
}

func calmAnswer(data PortalPageData) string {
	count := 0
	if data.Modules.Issues && len(data.Issues) > 0 {
		count++
	}
	if data.Modules.Events && len(data.Events) > 0 {
		count++
	}
	if data.Modules.Announcements && data.UnreadAnnouncements > 0 {
		count++
	}
	if count == 0 {
		return "Heute wartet nichts auf Sie."
	}
	if count == 1 {
		return "Eine Sache wartet auf Sie."
	}
	if count == 2 {
		return "Zwei Dinge warten auf Sie."
	}
	return "Drei Dinge warten auf Sie."
}

